# c3_collision.py -- REVIEW 6: exhibit two NON-ISOMORPHIC outer-labeled planar networks (order 0..5, three hybrid
# nodes, generated by the insertion procedure) with the SAME "unfolding" key, i.e. a pair that the survey identifies.
# Verifies non-isomorphism with networkx (leaf labels fixed), planarity by the wheel test, and compares the split
# systems and the sets of displayed trees; also evaluates the AUTHORS' unfolding_key on both networks.
import sys, pickle, itertools
import networkx as nx
from networkx.algorithms.isomorphism import DiGraphMatcher
from c1_survey import (N, FULL, parents, topo_children_first, keys_of, inv_of, system_of, wheel_planar, insertions)

prev = pickle.load(open("level_2.pkl", "rb"))
seen = {}          # key -> {inv: net}
found = []
for idx, (key, (net, root, _, _, _)) in enumerate(sorted(prev.items())):
    order0 = topo_children_first(net, root)
    for new in insertions(net, root, order0):
        order = topo_children_first(new, root)
        par = parents(new)
        k, iv = inv_of(new, root, order, par)
        d = seen.setdefault(k, {})
        if iv in d:
            continue
        s = system_of(new, root, order, par)
        if s is None or not wheel_planar(new):
            d[iv] = None
            continue
        d[iv] = (new, root, s)
        good = [v for v in d.values() if v is not None]
        if len(good) >= 2:
            found.append(k)
    if len(found) >= 1 and idx > 300:
        break
print("labelled keys carrying >= 2 planar networks with different INV (first", idx + 1, "parents):", len(set(found)))


def to_digraph(net):
    G = nx.DiGraph()
    for v, ch in net.items():
        G.add_node(v, lab=(v if v < N else -1))
        for c in ch:
            G.add_edge(v, c)
    return G


def tree_sets(net, root):
    order = topo_children_first(net, root)
    par = parents(net)
    hyb = [v for v in net if len(par[v]) == 2]
    out = set()
    for choice in itertools.product((0, 1), repeat=len(hyb)):
        keep = {h: par[h][c] for h, c in zip(hyb, choice)}
        mask = {}
        spl = set()
        for v in order:
            ch = net[v]
            if not ch:
                mask[v] = 1 << v
                continue
            m = 0
            for c in ch:
                if c in keep and keep[c] != v:
                    continue
                m |= mask[c]
            mask[v] = m
            if m and m != FULL:
                co = FULL ^ m
                if (m & (m - 1)) and (co & (co - 1)):
                    spl.add(min(m, co))
        out.add(frozenset(spl))
    return out


def authors_key(net, root):
    # the authors' unfolding_key, on their representation (leaf names "L0".., children lists)
    sys.path.insert(0, "../partA/authors_copy")
    import six_leaf_survey as S
    a = {(f"L{v}" if v < N else f"n{v}"): [(f"L{c}" if c < N else f"n{c}") for c in ch] for v, ch in net.items()}
    return S.unfolding_key(a, f"n{root}" if root >= N else f"L{root}", S.parents(a))


shown = 0
same_sys = diff_sys = same_trees = diff_trees = 0
for k in dict.fromkeys(found):
    good = [v for v in seen[k].values() if v is not None]
    (n1, r1, s1), (n2, r2, s2) = good[0], good[1]
    iso = DiGraphMatcher(to_digraph(n1), to_digraph(n2), node_match=lambda a, b: a["lab"] == b["lab"]).is_isomorphic()
    t1, t2 = tree_sets(n1, r1), tree_sets(n2, r2)
    same_sys += s1 == s2; diff_sys += s1 != s2
    same_trees += t1 == t2; diff_trees += t1 != t2
    if shown < 2:
        shown += 1
        print("\nKEY:", k)
        for nm, (nn, rr) in (("N1", (n1, r1)), ("N2", (n2, r2))):
            print(f"  {nm}: root {rr};", "; ".join(f"{v}->{list(ch)}" for v, ch in sorted(nn.items()) if ch))
            print(f"      planar (wheel test): {wheel_planar(nn)}; authors' unfolding_key: {authors_key(nn, rr)}")
        print("  isomorphic (leaf labels fixed, networkx):", iso)
        print("  same authors' key:", authors_key(n1, r1) == authors_key(n2, r2), " same split system:", s1 == s2, " same set of displayed trees:", t1 == t2)
    assert not iso
print(f"\namong {len(dict.fromkeys(found))} colliding keys examined: all pairs non-isomorphic; same split system {same_sys}, different {diff_sys}; "
      f"same set of displayed trees {same_trees}, different {diff_trees}")
